package com.company.tpm.dashboard;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class AnalyticsService{private final JdbcClient db;public AnalyticsService(JdbcClient d){db=d;}public record Metrics(long employees,long activeEmployees,long courses,long upcoming,double completion,double attendance,double passRate,long overdue,long failed,long expiring){}@Transactional(readOnly=true)public Metrics metrics(){return db.sql("select (select count(*) from employees) employees,(select count(*) from employees where status='ACTIVE') active_employees,(select count(*) from training_courses where active) courses,(select count(*) from training_sessions where status='SCHEDULED' and session_date>=current_date) upcoming,coalesce((select 100.0*count(*) filter(where status='COMPLETED')/nullif(count(*),0) from training_assignments),0) completion,coalesce((select 100.0*count(*) filter(where status in('PRESENT','LATE'))/nullif(count(*),0) from attendance),0) attendance,coalesce((select 100.0*count(*) filter(where result='PASSED')/nullif(count(*),0) from scores),0) pass_rate,(select count(*) from training_assignments where status='OVERDUE') overdue,(select count(*) from training_assignments where status='FAILED') failed,(select count(*) from certifications where expiry_date between current_date and current_date+30) expiring").query((rs,n)->new Metrics(rs.getLong(1),rs.getLong(2),rs.getLong(3),rs.getLong(4),rs.getDouble(5),rs.getDouble(6),rs.getDouble(7),rs.getLong(8),rs.getLong(9),rs.getLong(10))).single();}}
